async function execute(browser: WebFlowBrowserAPI, params: FlowParams): Promise<WebFlowResult> {
    const link = await browser.selectElement({
        condition: 'The main-document product detail link for ' + JSON.stringify(params.productName) + ', not an add-to-cart, checkout, sponsored alternative or unrelated recommendation control',
        capability: 'activate',
        frameScope: 'main-document'
    });
    if (link.role !== 'link') {
        throw new Error('The selected product detail control is not a link; no action attempted');
    }
    await browser.executeUiAction(link.targetId, { type: 'activate' });
    await browser.awaitPageLoad(params.navigationTimeoutMs);
    const result = await browser.evaluatePageCondition('The main document shows the primary product detail page for ' + JSON.stringify(params.productName) + ', including its requested variant, rather than a search listing or recommendation.', 'main-document');
    if (result.status !== 'matched') {
        throw new Error('Product destination was not verified (' + result.status + '). Navigation may have occurred; no retry.');
    }
    return { success: true, message: 'Verified main-document product page for ' + params.productName };
}
